package ledger

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

var (
	errInvalidLocale   = errors.New("invalid locale")
	errInvalidCurrency = errors.New("invalid currency")
	errInvalidDate     = errors.New("invalid date")
)

const (
	dateWidth        = 10
	descriptionWidth = 25
	changeWidth      = 13
)

type localeInfo struct {
	dateHeader, descriptionHeader, changeHeader string
	// formats a date "YYYY-MM-DD" for display
	formatDate func(string) (string, error)
	// formats a change in cents for display
	formatChange func(cents int) string
}

func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	info, ok := locales[locale]
	if !ok {
		return "", errInvalidLocale
	}
	symbol, ok := currencySymbols[currency]
	if !ok {
		return "", errInvalidCurrency
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		a, b := sorted[i], sorted[j]
		if a.Date != b.Date {
			return a.Date < b.Date
		}
		if a.Description != b.Description {
			return a.Description < b.Description
		}
		return a.Change < b.Change
	})

	var b strings.Builder
	b.WriteString(info.dateHeader)
	b.WriteString(strings.Repeat(" ", dateWidth-len(info.dateHeader)))
	b.WriteString(" | ")
	b.WriteString(info.descriptionHeader)
	b.WriteString(strings.Repeat(" ", descriptionWidth-len(info.descriptionHeader)))
	b.WriteString(" | ")
	b.WriteString(info.changeHeader)
	b.WriteByte('\n')

	for _, e := range sorted {
		date, err := info.formatDate(e.Date)
		if err != nil {
			return "", err
		}
		b.WriteString(date)
		b.WriteString(strings.Repeat(" ", dateWidth-len(date)))
		b.WriteString(" | ")
		b.WriteString(truncate(e.Description))
		b.WriteString(" | ")
		b.WriteString(info.formatChange(e.Change))
		b.WriteByte('\n')
	}
	return b.String(), nil
}
```

